export const duration=28;
export const config={title:'散熱蓋與 TIM 組裝',sceneLabel:'中央聚合物TIM與周邊蓋膠分工，熱由晶粒經TIM和金屬蓋交給外部散熱',question:'中央傳熱，周邊固定',overview:24,notes:['從已安裝晶粒的封裝開始。中央TIM1採矽膠導熱膏型代表，依Dow TC-5026的non-curing屬性；中央材料不做固化轉變。周邊膠採DOWSIL 3-6265類熱固化矽膠代表，固化的是周邊固定膠。兩種材料組合僅為教學模型，不宣稱已驗證的配方或組裝條件。','TIM填補晶粒頂面與蓋內表面間的微小空隙，降低接觸熱阻。短暫A放大圖將表面粗糙大幅放大；主圖的層厚亦不按比例。TIM沒有熔成焊料，顏色全程一致。','周邊蓋膠只在基板邊緣承接金屬蓋邊，與中央TIM分開。蓋下降後控制中央與周邊層厚，兩者不跨越晶粒側邊的保持淨空區。材料色用於辨識，並非商品實際顏色。','橙色箭頭代表定性熱傳路徑，熱由晶粒經TIM1進入金屬蓋，再穿過外部散熱邊界。邊界代表後續TIM2及散熱系統的總作用，不是蓋本身消滅熱量；本輪不裝散熱器、不求解溫度或流體。不同TIM配方的電性不一概而論。'],sources:[['Dow：TIM1與lid attach位置及角色','https://www.dow.com/en-us/market/mkt-electronics/sub-elec-mems-sensors-actuators.html'],['Dow：TC-5026為non-curing矽膠導熱材料','https://www.dow.com/en-us/market/mkt-electronics/sub-elec-data-center-cooling.html'],['Dow：3-6265周邊固定膠的熱固化屬性','https://www.dow.com/en-us/pdp.dowsil-3-6265-thixotropic-adhesive.02147483z.html'],['Dow Corning原始研究：蓋膠與TIM1介面、固化與相容性','https://imapsource.org/article/57437-adhesion-and-cure-mechanism-studies-for-advanced-lidded-flip-chip-applications/attachment/122710.pdf']]};
export const steps=[{end:4,title:'已裝晶粒與新蓋',key:3,what:'晶粒已裝在基板上；觀察晶粒頂面與蓋內表面的微小空隙。',detail:'A為粗糙度示意，尺寸大幅放大。此輪不重作固晶或底填。'},{end:10,title:'中央TIM與周邊膠',key:9,what:'中央晶粒頂面施加TIM，基板兩側蓋邊位置施加固定膠。',detail:'兩種顏色對應不同用途，中間保持淨空。'},{end:16,title:'對準下降與接觸',key:15.5,what:'金屬蓋下降，中央TIM展開填入間隙，蓋邊落在周邊膠上。',detail:'控制兩處層厚，材料不穿透晶粒、不流入側邊淨空區。'},{end:21,title:'蓋膠固化與層厚穩定',key:20,what:'周邊膠受熱固化，TIM維持受控的薄層接觸。',detail:'本例TIM是不固化導熱膏；不能把周邊膠的固化套用到它。'},{end:26,title:'熱交給外部散熱',key:24,what:'橙色熱流從晶粒經TIM到金屬蓋，繼續越過外部散熱邊界。',detail:'材料色與熱流分開；不顯示無依據的溫降或效率。'},{end:28,title:'完成件移交',key:26.3,what:'組裝件完整退場，下一輪由新封裝與新蓋開始。',detail:'固化膠不被吸回工具，TIM不倒流成施膠前狀態。'}];
export const ramp=(t,a,b)=>Math.max(0,Math.min(1,(t-a)/(b-a)));export const ease=x=>x*x*(3-2*x);
export function stateAt(t){t=Math.max(0,Math.min(duration-.0001,t));const index=steps.findIndex(s=>t<s.end),place=ease(ramp(t,10,15));return {t,index,step:steps[index],entry:ease(ramp(t,0,1)),tim:ramp(t,4,6),glue:ramp(t,6.5,9),place,squash:ramp(place,.84,1),rim:ramp(place,.91,1),cure:ramp(t,16,20),heat:t>=21&&t<26.5,exit:ease(ramp(t,26.5,27.8))};}
